let healthStore = HKHealthStore()
let stepsType = HKQuantityType.quantityType(forIdentifier: .stepCount)!

func requestPermissions() async throws {
    try await healthStore.requestAuthorization(toShare: [], read: [stepsType])
}

func stepsToday(completion: @escaping (Double?) -> Void) {
    let start = Calendar.current.startOfDay(for: Date())
    let predicate = HKQuery.predicateForSamples(withStart: start, end: Date())
    let query = HKStatisticsQuery(quantityType: stepsType,
                                  quantitySamplePredicate: predicate,
                                  options: .cumulativeSum) { _, result, _ in
        let count = result?.sumQuantity()?.doubleValue(for: .count())
        completion(count)
    }
    healthStore.execute(query)
}

