-- ─────────────────────────────────────────────────────────────────────────────
-- WotNow: Core schema, RLS policies, helper RPCs
-- Safe to run multiple times (idempotent where possible)
-- ─────────────────────────────────────────────────────────────────────────────

-- Extensions (UUID + crypto)
create extension if not exists "pgcrypto";
create extension if not exists "uuid-ossp";

-- USERS
create table if not exists public.users (
  user_id uuid primary key default gen_random_uuid(),
  email text unique,
  created_at timestamptz not null default now()
);

-- DEVICES (guest linkage; device_id lives on-device via Capacitor)
create table if not exists public.devices (
  device_id text primary key,
  user_id uuid references public.users(user_id) on delete set null,
  created_at timestamptz not null default now()
);

-- PROFILES
create table if not exists public.profiles (
  user_id uuid primary key references public.users(user_id) on delete cascade,
  display_name text,
  units text not null default 'metric' check (units in ('metric','imperial')),
  health_opt_in boolean not null default false
);

-- LOCATIONS
create table if not exists public.locations (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.users(user_id) on delete cascade,
  label text,
  lat double precision not null,
  lon double precision not null,
  type text not null default 'favourite' check (type in ('home','coastal','favourite')),
  created_at timestamptz not null default now()
);

-- ENTITLEMENTS
create table if not exists public.entitlements (
  user_id uuid primary key references public.users(user_id) on delete cascade,
  pro boolean not null default false,
  pro_expires_at timestamptz,
  packs jsonb not null default '[]'::jsonb   -- e.g. ["snow","surf_sea","fishing","grow"]
);

-- RECEIPTS (raw store payloads; avoid PII)
create table if not exists public.receipts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.users(user_id) on delete cascade,
  store text not null check (store in ('appstore','play','web')),
  product_id text not null,
  raw jsonb not null,
  created_at timestamptz not null default now()
);

-- ACTIVITY HISTORY (keep light)
create table if not exists public.activity_history (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references public.users(user_id) on delete cascade,
  activity_id text not null,
  started_at timestamptz not null,
  duration_minutes int,
  notes text
);

-- ─────────────────────────────────────────────────────────────────────────────
-- RLS (Row Level Security)
-- ─────────────────────────────────────────────────────────────────────────────
alter table public.devices enable row level security;
alter table public.profiles enable row level security;
alter table public.locations enable row level security;
alter table public.entitlements enable row level security;
alter table public.activity_history enable row level security;
alter table public.receipts enable row level security;
alter table public.users enable row level security;

-- Users table: allow self-read (optional), admin writes via service key only
drop policy if exists users_self_read on public.users;
create policy users_self_read on public.users
  for select using (auth.uid() = user_id);

-- Devices: we’ll access via a secure RPC that checks device_id equality
drop policy if exists devices_open_read on public.devices;
drop policy if exists devices_open_write on public.devices;
create policy devices_open_read on public.devices
  for select using (true);
create policy devices_open_write on public.devices
  for insert with check (true);

-- Profiles: owner read/write
drop policy if exists profiles_rw on public.profiles;
create policy profiles_rw on public.profiles
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- Locations: owner read/write
drop policy if exists locations_rw on public.locations;
create policy locations_rw on public.locations
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- Entitlements: owner read, writes via server or secure RPC
drop policy if exists entitlements_r on public.entitlements;
create policy entitlements_r on public.entitlements
  using (auth.uid() = user_id);

-- Activity history: owner read/write
drop policy if exists activity_history_rw on public.activity_history;
create policy activity_history_rw on public.activity_history
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- Receipts: owner read, writes via server key
drop policy if exists receipts_r on public.receipts;
create policy receipts_r on public.receipts
  using (auth.uid() = user_id);

-- ─────────────────────────────────────────────────────────────────────────────
-- Helper RPCs (auth definer where appropriate)
-- ─────────────────────────────────────────────────────────────────────────────

-- Attach a device to a user (on sign-in)
create or replace function public.attach_device_to_user(p_device_id text)
returns void
language plpgsql
security definer
as $$
begin
  -- Ensure a row exists
  insert into public.devices (device_id, user_id)
  values (p_device_id, auth.uid())
  on conflict (device_id) do update set user_id = auth.uid();
end;
$$;

revoke all on function public.attach_device_to_user(text) from public;
grant execute on function public.attach_device_to_user(text) to authenticated;

-- Merge guest data to the authenticated user
-- (Here we only track devices. If you temporarily stored guest rows without user_id,
-- you’d add updates here to reassign them.)
create or replace function public.merge_guest_to_user(p_device_id text)
returns void
language plpgsql
security definer
as $$
begin
  update public.devices
     set user_id = auth.uid()
   where device_id = p_device_id;

  -- If you ever stored guest-owned rows with NULL user_id, reassign here.
  -- Example (only if you used NULL user_id for guest):
  -- update public.locations set user_id = auth.uid() where user_id is null and device_id = p_device_id;
end;
$$;

revoke all on function public.merge_guest_to_user(text) from public;
grant execute on function public.merge_guest_to_user(text) to authenticated;

-- Upsert entitlements (server-only; use service key)
create or replace function public.upsert_entitlements(
  p_user_id uuid,
  p_pro boolean,
  p_pro_expires_at timestamptz,
  p_packs jsonb
) returns void
language plpgsql
security definer
as $$
begin
  insert into public.entitlements (user_id, pro, pro_expires_at, packs)
  values (p_user_id, p_pro, p_pro_expires_at, coalesce(p_packs, '[]'::jsonb))
  on conflict (user_id) do update
    set pro = excluded.pro,
        pro_expires_at = excluded.pro_expires_at,
        packs = excluded.packs;
end;
$$;

revoke all on function public.upsert_entitlements(uuid, boolean, timestamptz, jsonb) from public;
grant execute on function public.upsert_entitlements(uuid, boolean, timestamptz, jsonb) to service_role;

-- Insert receipt (server-only)
create or replace function public.insert_receipt(
  p_user_id uuid,
  p_store text,
  p_product_id text,
  p_raw jsonb
) returns uuid
language plpgsql
security definer
as $$
declare
  v_id uuid := gen_random_uuid();
begin
  insert into public.receipts (id, user_id, store, product_id, raw)
  values (v_id, p_user_id, p_store, p_product_id, p_raw);
  return v_id;
end;
$$;

revoke all on function public.insert_receipt(uuid, text, text, jsonb) from public;
grant execute on function public.insert_receipt(uuid, text, text, jsonb) to service_role;

-- Convenience view: current user’s entitlements (client-readable)
create or replace view public.my_entitlements as
  select e.*
  from public.entitlements e
  where e.user_id = auth.uid();

grant select on public.my_entitlements to authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- Defaults & sanity seeds (optional)
-- ─────────────────────────────────────────────────────────────────────────────
-- insert into public.entitlements (user_id, pro, packs) values ('00000000-0000-0000-0000-000000000000', false, '[]')
-- on conflict do nothing;

