import Foundation
import Capacitor
import HealthKit

@objc(HealthKitPlugin)
public class HealthKitPlugin: CAPPlugin {
    private let healthStore = HKHealthStore()

    private func stepsType() -> HKQuantityType {
        return HKObjectType.quantityType(forIdentifier: .stepCount)!
    }
    private func distanceType() -> HKQuantityType {
        return HKObjectType.quantityType(forIdentifier: .distanceWalkingRunning)!
    }

    @objc func isAvailable(_ call: CAPPluginCall) {
        call.resolve(["available": HKHealthStore.isHealthDataAvailable()])
    }

    @objc func requestAuthorization(_ call: CAPPluginCall) {
        let readTypes: Set<HKObjectType> = [stepsType(), distanceType(), HKObjectType.workoutType()]
        healthStore.requestAuthorization(toShare: nil, read: readTypes) { success, error in
            if let error = error {
                call.reject("Health auth failed: \(error.localizedDescription)")
                return
            }
            call.resolve(["granted": success])
        }
    }

    @objc func stepsToday(_ call: CAPPluginCall) {
        let now = Date()
        let start = Calendar.current.startOfDay(for: now)
        let predicate = HKQuery.predicateForSamples(withStart: start, end: now, options: .strictStartDate)

        let query = HKStatisticsQuery(quantityType: stepsType(),
                                      quantitySamplePredicate: predicate,
                                      options: .cumulativeSum) { _, stats, error in
            if let error = error {
                call.reject("stepsToday error: \(error.localizedDescription)")
                return
            }
            let qty = stats?.sumQuantity()?.doubleValue(for: HKUnit.count())
            call.resolve(["steps": qty ?? 0])
        }
        healthStore.execute(query)
    }

    @objc func distanceToday(_ call: CAPPluginCall) {
        let now = Date()
        let start = Calendar.current.startOfDay(for: now)
        let predicate = HKQuery.predicateForSamples(withStart: start, end: now, options: .strictStartDate)

        let query = HKStatisticsQuery(quantityType: distanceType(),
                                      quantitySamplePredicate: predicate,
                                      options: .cumulativeSum) { _, stats, error in
            if let error = error {
                call.reject("distanceToday error: \(error.localizedDescription)")
                return
            }
            let metres = stats?.sumQuantity()?.doubleValue(for: HKUnit.meter())
            call.resolve(["metres": metres ?? 0])
        }
        healthStore.execute(query)
    }

    @objc func recentWorkouts(_ call: CAPPluginCall) {
        let workoutType = HKObjectType.workoutType()
        let sinceMinutes = call.getInt("sinceMinutes") ?? 1440
        let fromDate = Calendar.current.date(byAdding: .minute, value: -sinceMinutes, to: Date()) ?? Date.distantPast
        let predicate = HKQuery.predicateForSamples(withStart: fromDate, end: Date(), options: .strictStartDate)

        let query = HKSampleQuery(sampleType: workoutType, predicate: predicate, limit: 50, sortDescriptors: nil) { _, samples, error in
            if let error = error {
                call.reject("recentWorkouts error: \(error.localizedDescription)")
                return
            }
            let workouts = (samples as? [HKWorkout] ?? []).map { w in
                return [
                    "start": ISO8601DateFormatter().string(from: w.startDate),
                    "end": ISO8601DateFormatter().string(from: w.endDate),
                    "activityType": w.workoutActivityType.rawValue,
                    "totalEnergyBurned": w.totalEnergyBurned?.doubleValue(for: HKUnit.kilocalorie()) ?? 0,
                    "totalDistanceMetres": w.totalDistance?.doubleValue(for: HKUnit.meter()) ?? 0
                ] as [String : Any]
            }
            call.resolve(["workouts": workouts])
        }
        healthStore.execute(query)
    }
}

