// src/hooks/useHealthSummary.ts
import { useEffect, useState } from 'react';
import { HealthKit } from '@/plugins/healthkit';

type Summary = { available: boolean; steps: number; metres: number; loading: boolean; error?: string };

export function useHealthSummary() {
  const [state, setState] = useState<Summary>({ available: false, steps: 0, metres: 0, loading: true });

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const { available } = await HealthKit.isAvailable();
        if (!available) {
          if (mounted) setState(s => ({ ...s, available: false, loading: false }));
          return;
        }
        await HealthKit.requestAuthorization();
        const [{ steps }, { metres }] = await Promise.all([
          HealthKit.stepsToday(),
          HealthKit.distanceToday()
        ]);
        if (mounted) setState({ available: true, steps, metres, loading: false });
      } catch (e: any) {
        if (mounted) setState({ available: false, steps: 0, metres: 0, loading: false, error: String(e?.message || e) });
      }
    })();
    return () => { mounted = false; };
  }, []);

  return state;
}

