#!/usr/bin/env python3
import json
import sys

RULES_FILE = "rules/eggs-doctor-rules.json"

def load(path):
    with open(path) as f:
        return json.load(f)

def get_nested(data, path):
    keys = path.split(".")
    for k in keys:
        if isinstance(data, dict) and k in data:
            data = data[k]
        else:
            return None
    return data

def match_condition(value, condition):
    if isinstance(condition, dict):
        if "lt" in condition:
            return value is not None and value < condition["lt"]
        if "gt" in condition:
            return value is not None and value > condition["gt"]
        if "not" in condition:
            return value != condition["not"]
        if "any" in condition:
            return value in condition["any"]
        return False
    return value == condition

def match_rule(rule, fixture):
    for key, condition in rule["match"].items():
        value = get_nested(fixture, key)
        if not match_condition(value, condition):
            return False
    return True

fixture = load(sys.argv[1])
ruleset = load(RULES_FILE)["rules"]

hits = [r for r in ruleset if match_rule(r, fixture)]

def print_section(title, items):
    if not items:
        return
    print(f"## {title}")
    for r in items:
        print(f"- **{r['id']}**: {r['explanation']}")
    print()

print("# 🥚 Penguins-Eggs Doctor Report\n")

if not hits:
    print("✔ No issues detected")
    sys.exit(0)

print_section("CRITICAL", [r for r in hits if r["severity"] == "critical"])
print_section("WARNINGS", [r for r in hits if r["severity"] == "warning"])
print_section("INFO", [r for r in hits if r["severity"] == "info"])

