import time
from functools import wraps
from opentelemetry import trace

# Global variable to keep track of the last trace time
last_trace_time = 0

def trace_decorator(func):
    global last_trace_time

    @wraps(func)
    def wrapper(*args, **kwargs):
        nonlocal last_trace_time
        current_time = time.time()

        # Check if it's time to send a new trace (first trace or 5 minutes passed)
        if last_trace_time == 0 or (current_time - last_trace_time) >= 300:
            # If it's time, update the last trace time and proceed with tracing
            last_trace_time = current_time
            tracer = trace.get_tracer(__name__)

            with tracer.start_as_current_span(func.__name__) as span:
                try:
                    # Execute the wrapped function and return its result
                    return func(*args, **kwargs)
                except Exception as e:
                    # Record the exception in the span and re-raise it
                    span.record_exception(e)
                    raise
        else:
            # If it's not time, skip tracing and just call the function
            return func(*args, **kwargs)

    return wrapper

