@Service
class UpdateRouter(
  private val userService: UserService,
  private val customerMessageService: CustomerMessageService,
  private val operatorMessageService: OperatorMessageService,
  private val callbackService: CallbackService
) {
  fun handle(update: Update, bot: TelegramLongPollingBot) {
    when {
      update.hasCallbackQuery() -> callbackService.handle(update.callbackQuery, bot)
      update.hasMessage() -> {
        val msg = update.message
        val from = msg.from
        val user = userService.upsertFromTelegram(from)

        if (user.role == Role.OPERATOR || user.role == Role.ADMIN) {
          operatorMessageService.handleOperatorMessage(user, msg, bot)
        } else {
          customerMessageService.handleCustomerMessage(user, msg, bot)
        }
      }
    }
  }
}

