@Service
class AssignmentService(
  private val sessionRepo: SessionRepository,
  private val operatorStatusRepo: OperatorStatusRepository
) {

  @Transactional
  fun tryAssignNextCustomer(operatorUserId: UUID): SessionEntity? {
    val opStatus = operatorStatusRepo.findByOperatorUserIdForUpdate(operatorUserId)
      ?: throw IllegalStateException("Operator status missing")

    if (opStatus.state != OperatorState.AVAILABLE) return null
    if (opStatus.activeSessionId != null) return null

    val session = sessionRepo.lockOldestWaiting() ?: return null

    session.status = SessionStatus.ACTIVE
    session.operatorUserId = operatorUserId
