@Service
class CustomerMessageService(
  private val sessionService: SessionService,
  private val messageService: MessageService,
  private val operatorNotifier: OperatorNotifier
) {
  fun handleCustomerMessage(customer: UserEntity, msg: Message, bot: TelegramLongPollingBot) {
    val session = sessionService.getOrCreateOpenSessionForCustomer(customer.id)

    messageService.saveCustomerMessage(session.id, customer.id, msg)

    when (session.status) {
      SessionStatus.ACTIVE -> operatorNotifier.forwardToOperator(session, msg, bot)
      SessionStatus.WAITING -> bot.execute(SendMessage(msg.chatId.toString(),
        "Thanks! You’re in the queue. An operator will reply soon."))
      else -> bot.execute(SendMessage(msg.chatId.toString(),
        "This chat is closed. Send a new message to start again."))
    }
  }
}

