@Service
class AssignmentService(
  private val sessionRepo: SessionRepository,
  private val operatorStatusRepo: OperatorStatusRepository
) {

  @Transactional
  fun tryAssignNext(operatorUserId: UUID): SessionEntity? {
    val op = operatorStatusRepo.findByOperatorUserIdForUpdate(operatorUserId)
      ?: throw IllegalStateException("Operator status missing")

    if (op.state != OperatorState.AVAILABLE) return null
    if (op.activeSessionId != null) return null

    val session = sessionRepo.lockOldestWaitingForOperatorLanguages(operatorUserId)
      ?: return null

    session.status = SessionStatus.ACTIVE
    session.operatorUserId = operatorUserId
    session.assignedAt = Instant.now()

    op.state = OperatorState.BUSY
    op.activeSessionId = session.id
    op.updatedAt = Instant.now()

    return session
  }
}

