package com.yourcompany.supportbot.service

import com.yourcompany.supportbot.db.entity.AppUserEntity
import com.yourcompany.supportbot.db.entity.UserStateEntity
import com.yourcompany.supportbot.db.repo.AppUserRepository
import com.yourcompany.supportbot.db.repo.UserStateRepository
import com.yourcompany.supportbot.domain.OnboardingState
import com.yourcompany.supportbot.domain.Role
import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import org.telegram.telegrambots.meta.api.objects.User
import java.time.Instant

@Service
class UserService(
    private val userRepo: AppUserRepository,
    private val stateRepo: UserStateRepository
) {

    @Transactional
    fun upsertTelegramUser(tg: User): Pair<AppUserEntity, UserStateEntity> {
        val telegramUserId = tg.id.toLong()

        val user = userRepo.findByTelegramUserId(telegramUserId)
            ?.apply {
                username = tg.userName
                displayName = listOfNotNull(tg.firstName, tg.lastName).joinToString(" ").ifBlank { null }
                updatedAt = Instant.now()
            }
            ?: userRepo.save(
                AppUserEntity(
                    telegramUserId = telegramUserId,
                    username = tg.userName,
                    displayName = listOfNotNull(tg.firstName, tg.lastName).joinToString(" ").ifBlank { null },
                    role = Role.CUSTOMER
                )
            )

        val state = stateRepo.findById(user.id).orElseGet {
            stateRepo.save(UserStateEntity(userId = user.id, user = user, state = OnboardingState.NEED_LANG))
        }

        return user to state
    }
}

