package com.yourcompany.supportbot.bot.handler

import com.yourcompany.supportbot.bot.ui.BotUi
import com.yourcompany.supportbot.domain.OnboardingState
import com.yourcompany.supportbot.service.UserService
import org.springframework.stereotype.Component
import org.telegram.telegrambots.meta.api.methods.send.SendMessage
import org.telegram.telegrambots.meta.api.objects.Message
import org.telegram.telegrambots.meta.generics.TelegramClient

@Component
class MessageHandler(
    private val telegramClient: TelegramClient,
    private val userService: UserService
) {

    fun handle(message: Message) {
        val from = message.from ?: return
        val (user, state) = userService.upsertTelegramUser(from)
        val chatId = message.chatId.toString()

        when (state.state) {
            OnboardingState.NEED_LANG -> {
                telegramClient.execute(
                    SendMessage(chatId, BotUi.chooseLanguageText()).apply {
                        replyMarkup = BotUi.languageKeyboard()
                    }
                )
            }

            OnboardingState.NEED_PHONE -> {
                // For now we only prompt. Actual contact processing is Step 6.
                val lang = user.preferredLang
                if (lang == null) {
                    // safety fallback
                    telegramClient.execute(
                        SendMessage(chatId, BotUi.chooseLanguageText()).apply {
                            replyMarkup = BotUi.languageKeyboard()
                        }
                    )
                    return
                }

                // If they didn't send a contact, remind them to use the button.
                if (message.contact == null) {
                    telegramClient.execute(
                        SendMessage(chatId, BotUi.mustUsePhoneButton(lang)).apply {
                            replyMarkup = BotUi.phoneKeyboard(lang)
                        }
                    )
                }
            }

            OnboardingState.READY -> {
                telegramClient.execute(SendMessage(chatId, "✅ Onboarding complete (next: sessions + queue)."))
            }
        }
    }
}

