        val data = callback.data ?: return

        val lang = when (data) {
            "LANG_UZ" -> Lang.UZ
            "LANG_EN" -> Lang.EN
            "LANG_RU" -> Lang.RU
            else -> null
        }

        if (lang != null) {
            onboardingService.setLanguage(user.id, lang)

            telegramClient.execute(
                SendMessage(chatId, BotUi.askPhoneText(lang)).apply {
                    replyMarkup = BotUi.phoneKeyboard(lang)
                }
            )
        }

        // Always acknowledge callback click (removes “loading” in Telegram UI)
        telegramClient.execute(
            AnswerCallbackQuery(callback.id)
        )
    }
}

