import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional
import org.telegram.telegrambots.meta.api.objects.User
import java.time.Instant

@Service
class UserService(
    private val userRepo: AppUserRepository,
    private val stateRepo: UserStateRepository
) {
    @Transactional
    fun upsertTelegramUser(tg: User): Pair<AppUserEntity, UserStateEntity> {
        val tgId = tg.id.toLong()

        val user = userRepo.findByTelegramUserId(tgId)?.apply {
            username = tg.userName
            displayName = listOfNotNull(tg.firstName, tg.lastName).joinToString(" ").ifBlank { null }
            // updatedAt handled by auditing
        } ?: userRepo.save(
            AppUserEntity(
                telegramUserId = tgId,
                username = tg.userName,
                displayName = listOfNotNull(tg.firstName, tg.lastName).joinToString(" ").ifBlank { null }
            )
        )

        val state = stateRepo.findByUser_Id(user.id!!) ?: stateRepo.save(
            UserStateEntity(user = user, state = OnboardingState.NEED_LANG)
        )

        return user to state
    }
}

@Service
class OnboardingService(
    private val userRepo: AppUserRepository,
    private val stateRepo: UserStateRepository
) {
    @Transactional
    fun setLanguage(userId: Long, lang: Lang) {
        val user = userRepo.findById(userId).orElseThrow()
        user.preferredLang = lang

        val state = stateRepo.findByUser_Id(userId) ?: throw IllegalStateException("UserState missing")
        state.state = OnboardingState.NEED_PHONE
    }
}

