import java.time.Instant

@Service
class OnboardingService(
    private val userRepo: AppUserRepository,
    private val stateRepo: UserStateRepository
) {
    @Transactional
    fun setLanguage(userId: Long, lang: Lang) {
        val user = userRepo.findById(userId).orElseThrow()
        user.preferredLang = lang

        val state = stateRepo.findByUser_Id(userId) ?: throw IllegalStateException("UserState missing")
        state.state = OnboardingState.NEED_PHONE
    }

    @Transactional
    fun savePhoneAndMarkReady(userId: Long, telegramUserId: Long, rawPhone: String) {
        val user = userRepo.findById(userId).orElseThrow()

        val lang = user.preferredLang ?: throw InvalidOnboardingStateException(
            "NEED_PHONE but preferredLang is null (userId=$userId, telegramUserId=$telegramUserId)"
        )

        val state = stateRepo.findByUser_Id(userId) ?: throw IllegalStateException("UserState missing")
        if (state.state != OnboardingState.NEED_PHONE) {
            throw InvalidOnboardingStateException("Expected NEED_PHONE but was ${state.state} (userId=$userId)")
        }

        val normalized = normalizePhone(rawPhone)

        // If phone belongs to another telegram user => block
        val existing = userRepo.findByPhoneE164(normalized)
        if (existing != null && existing.telegramUserId != telegramUserId) {
            throw PhoneAlreadyLinkedException("Phone already linked to another user. phone=$normalized")
        }

        user.phoneE164 = normalized

        state.state = OnboardingState.READY
    }

    private fun normalizePhone(raw: String): String {
        // Simple, safe normalization:
        // - keep digits only
        // - if starts with 998... keep as +998...
        // - if starts with 0 and length looks like local, you can adjust later
        val digits = raw.filter { it.isDigit() }

        // If already includes country digits (e.g., 998901234567)
        return if (digits.startsWith("998")) {
            "+$digits"
        } else if (digits.startsWith("7") && digits.length >= 11) {
            "+$digits" // Russia/KZ-like numbers
        } else if (digits.startsWith("1") && digits.length >= 11) {
            "+$digits" // US-like
        } else if (digits.startsWith("0")) {
            // ambiguous; keep as +<digits without leading zeros is risky
            // simplest MVP: store as +<digits> if it looks international otherwise just +digits
            "+${digits.trimStart('0')}"
        } else {
            "+$digits"
        }
    }
}

