OnboardingState.NEED_PHONE -> {
    val lang = user.preferredLang
    if (lang == null) {
        println(
            "⚠️ [Onboarding] Inconsistent state: NEED_PHONE but preferredLang is null " +
                "(userId=${user.id}, telegramUserId=${user.telegramUserId})"
        )
        telegramClient.execute(
            SendMessage(chatId, BotUi.chooseLanguageText()).apply {
                replyMarkup = BotUi.languageKeyboard()
            }
        )
        return
    }

    val contact = message.contact
    if (contact == null) {
        telegramClient.execute(
            SendMessage(chatId, BotUi.mustUsePhoneButton(lang)).apply {
                replyMarkup = BotUi.phoneKeyboard(lang)
            }
        )
        return
    }

    // Validate "self contact" if Telegram provided userId
    val contactUserId = contact.userId
    if (contactUserId != null && contactUserId.toLong() != user.telegramUserId) {
        telegramClient.execute(
            SendMessage(chatId, BotUi.invalidContactOwnerText(lang)).apply {
                replyMarkup = BotUi.phoneKeyboard(lang)
            }
        )
        return
    }

    try {
        onboardingService.savePhoneAndMarkReady(
            userId = user.id!!,
            telegramUserId = user.telegramUserId,
            rawPhone = contact.phoneNumber
        )

        telegramClient.execute(
            SendMessage(chatId, BotUi.phoneSavedText(lang))
        )
    } catch (e: PhoneAlreadyLinkedException) {
        telegramClient.execute(
            SendMessage(chatId, BotUi.phoneAlreadyLinkedText(lang))
        )
    } catch (e: Exception) {
        // keep it simple; log for dev
        println("❌ [Onboarding] Failed to save phone: ${e.message}")
        telegramClient.execute(
            SendMessage(chatId, BotUi.mustUsePhoneButton(lang)).apply {
                replyMarkup = BotUi.phoneKeyboard(lang)
            }
        )
    }
