    {
        // Get available TCP and UDP ports
        var tcpPort = Extensions.GetAvailableTcpPort();
        var udpPort = Extensions.GetAvailableUdpPort();

        // Set up the OSCQuery service
        var oscQuery = new OSCQueryServiceBuilder()
            .WithDefaults()
