    // Print a single OSCQueryNode (and assume it has a Name and possibly a Description)
    static void PrintNode(OSCQueryNode node, string path = "")
    {
        // Build the full path of the current node
        string currentPath = $"{path}/{node.Name}";

        // Print the current node's path and description
        Console.WriteLine($"Endpoint: {currentPath}, Description: {node.Description}");

        // Check if there are children nodes (sub-endpoints)
        if (node.Children != null)
        {
            foreach (var child in node.Children.Values)
            {
                // Recursively print child nodes
                PrintNode(child, currentPath);
            }
        }
    }
}

