                    Invalid email format
                </p>
                )}
            </div>
            <div className={styles['ResetPassword__sendButtonContainer']}>
                <Button className={styles['ResetPassword__sendButton']}>
                    SEND
                </Button>
            </div>
        </div >
    );
}

