    fetch(backendURL + "/products")
      .then(res => res.json())
      .then(data => {
        console.log("Products loaded:", data);
        setProducts(data);
      })
      .catch(err => {
        console.log("Products error:", err);
      });

  }, []);

  // Navigation render function
  const renderPage = () => {

    switch(currentPage) {

      case 'home':
        return <HomePage />;

      case 'profile':
        return <ProfilePage />;

      case 'news':
        return <NewsPage />;

      case 'products':
        return <ProductsPage products={products} />;

      case 'about':
        return <AboutPage />;

      default:
        return <HomePage />;
    }
  };

  return (

    <AppContext.Provider value={{ products }}>

