def map_colname_colid_zotero(zotero_connection, collection_name=None, depth=-1):
    """
    Returns a map of collection names to collection ids.

    :param zotero_connection: Pyzotero connection object.
    :param collection_name: (Optional) Name of a specific collection to map.
    :param depth: (Optional) Depth of search for subcollections. Default is -1 for unlimited depth.
    :return: Dictionary mapping collection names to their ids.
    """

    def map_collections(collection_id=None, current_depth=0):
        # If the depth limit is reached, stop the recursion
        if depth >= 0 and current_depth > depth:
            return {}

        collections_map = {}
        collections = zotero_connection.collections(collection_id)
        for c in collections:
            collections_map[c['data']['name']] = c['data']['key']
            # Recursively map subcollections
            collections_map.update(map_collections(c['data']['key'], current_depth + 1))

        return collections_map

    if collection_name:
        # If a specific collection is requested, find its ID first
        all_collections = zotero_connection.collections()
        collection_id = next((c['data']['key'] for c in all_collections if c['data']['name'] == collection_name), None)
        if not collection_id:
            raise ValueError(f"Collection named '{collection_name}' not found.")
        return map_collections(collection_id, 0)
    else:
        # Map all collections if no specific collection name is given
        return map_collections()

