describe('MapManagerService - captureMapAsImage', () => {
    let service: MapManagerService;

    beforeEach(() => {
        TestBed.configureTestingModule({
            providers: [MapManagerService],
        });

        service = TestBed.inject(MapManagerService);
    });

    it('should capture the map as an image and update currentMap.imageData', async () => {
        const mockCanvas = document.createElement('canvas');
        const mockImgData = 'data:image/jpeg;base64,mockImageData';
        const mapElement = document.createElement('div');
        mapElement.classList.add('map-container');

        // Spy on html2canvas to mock its behavior
        spyOn(html2canvas, 'default').and.returnValue(Promise.resolve(mockCanvas));

        // Spy on canvas.toDataURL to return mock image data
        spyOn(mockCanvas, 'toDataURL').and.returnValue(mockImgData);

        // Spy on querySelector to return the mock map element
        spyOn(document, 'querySelector').and.returnValue(mapElement);

        // Spy on document.createElement and appendChild
        const linkSpy = jasmine.createSpyObj('HTMLAnchorElement', ['click']);
        spyOn(document, 'createElement').and.returnValue(linkSpy);
        spyOn(document.body, 'appendChild');
        spyOn(document.body, 'removeChild');

        // Call the function
        await service.captureMapAsImage();

        // Assertions
        expect(document.querySelector).toHaveBeenCalledWith('.map-container');
        expect(html2canvas.default).toHaveBeenCalledWith(mapElement);
        expect(mockCanvas.toDataURL).toHaveBeenCalledWith('image/jpeg', 0.3);
        expect(service.currentMap.imageData).toEqual(mockImgData);

        // Check if the link was created and triggered
        expect(document.createElement).toHaveBeenCalledWith('a');
        expect(linkSpy.download).toEqual('screenshot.png');
        expect(linkSpy.href).toEqual(mockImgData);
        expect(document.body.appendChild).toHaveBeenCalledWith(linkSpy);
        expect(linkSpy.click).toHaveBeenCalled();
        expect(document.body.removeChild).toHaveBeenCalledWith(linkSpy);
