    it('should handle the case when the map container is not found', async () => {
        // Spy on querySelector to return null (simulating no map container found)
        spyOn(document, 'querySelector').and.returnValue(null);

        // Spy on html2canvas to ensure it's never called if mapElement is null
        const html2canvasSpy = spyOn(html2canvas, 'default');

        // Call the function
        await service.captureMapAsImage();

        // Ensure html2canvas is not called since the mapElement is null
        expect(html2canvasSpy).not.toHaveBeenCalled();
    });
});

