handleError(): (error: HttpErrorResponse) => Observable<never> {
    return (error: HttpErrorResponse) => {
        console.log(error.error);
        let errorMessage: string;

        // Check for client-side errors
        if (error.error instanceof ErrorEvent) {
            errorMessage = `Client-side error: ${error.error.message}`;
        } 
        // Check if the error response has the expected server-side structure
        else if (error.error && typeof error.error === 'object' && error.error.message) {
            errorMessage = `Server-side error: ${error.error.message}`;
        } 
        // Fallback for unexpected server error formats
        else {
            errorMessage = `Server-side error: ${error.status} - ${error.error?.error || 'Unknown error'}`;
        }

        // Log the error message
        console.error(errorMessage);

        // Throw the error to be handled by the caller
        return throwError(() => new Error(errorMessage));
    };
}

