)

func Update(m model.Model, ev events.Event) model.Model {
	m.Error = ""
	m.StatusMsg = ""

	switch ev.Event {

	case events.EventSearch:
		m.Query = ev.Payload["query"].(string)
		m.Loading = true
		m.View = model.ViewSearch

	case events.EventSelect:
		idx := int(ev.Payload["index"].(float64))
		if idx >= 0 && idx < len(m.Packages) {
			m.Selected = &m.Packages[idx]
			m.View = model.ViewDetails
		}

	case events.EventInstall:
		if m.Selected != nil {
			m.Build = &model.Build{
				Package: m.Selected.Name,
				Phase:   "install",
				Running: true,
			}
			m.View = model.ViewBuild
		}

	case events.EventRemove:
		if m.Selected != nil {
			m.Selected.Installed = false
			m.StatusMsg = "Package removed"
		}

	case events.EventNavigate:
		if v, ok := ev.Payload["view"].(string); ok {
			m.View = model.View(v)
		}
	}

	return m
}

