var (
	titleStyle  = lipgloss.NewStyle().Bold(true)
	statusStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("10"))
	errorStyle  = lipgloss.NewStyle().Foreground(lipgloss.Color("9"))
)

func View(m model.Model) string {
	var b strings.Builder

	b.WriteString(titleStyle.Render("Soar Package Manager\n\n"))

	switch m.View {
	case model.ViewSearch:
		b.WriteString(SearchView(m))
	case model.ViewDetails:
		b.WriteString(DetailsView(m))
	case model.ViewBuild:
		b.WriteString(BuildView(m))
	}

	if m.StatusMsg != "" {
		b.WriteString("\n" + statusStyle.Render(m.StatusMsg))
	}
	if m.Error != "" {
		b.WriteString("\n" + errorStyle.Render(m.Error))
	}

	return b.String()
}

