package view

import (
	"fmt"
	"strings"

	"github.com/pkgforge/soar-ui-core/model"
)

func BuildView(m model.Model) string {
	if m.Build == nil {
		return "No build running\n"
	}

	b := m.Build
	s := fmt.Sprintf("Installing %s (%s)\n\n", b.Package, b.Phase)

	for _, line := range b.Logs {
		s += line + "\n"
	}

	if b.Running {
		s += "\n[Building…]"
	}
	if b.Failed {
		s += "\n[FAILED]"
	}

	return strings.TrimSpace(s)
}

