func HandleKey(msg tea.KeyMsg) *events.Event {
	switch msg.String() {

	case "/":
		return &events.Event{
			Event: events.EventNavigate,
			Payload: map[string]any{"view": "search"},
		}

	case "enter":
		return &events.Event{
			Event: events.EventSelect,
			Payload: map[string]any{"index": 0},
		}

	case "i":
		return &events.Event{Event: events.EventInstall}

	case "r":
		return &events.Event{Event: events.EventRemove}

	case "s":
		return &events.Event{
			Event: events.EventNavigate,
			Payload: map[string]any{"view": "stores"},
		}

	case "esc", "b":
		return &events.Event{
			Event: events.EventNavigate,
			Payload: map[string]any{"view": "search"},
		}

	case "q", "ctrl+c":
		return &events.Event{Event: events.EventQuit}
	}

	return nil
}

