func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {

	case tea.KeyMsg:
		switch msg.String() {

		case "ctrl+c", "q":
			return m, tea.Quit

		case "up", "k":
			if m.cursor > 0 {
				m.cursor--
			}

		case "down", "j":
			if m.cursor < len(m.items)-1 {
				m.cursor++
			}

		case "tab":
			m.pane = (m.pane + 1) % 3

		case "/":
			return m, startSearchCmd()

		case "i":
			return m, installCmd(m.items[m.cursor])

		case "o":
			m.offline = !m.offline
			m.status = "Offline mode toggled"

		case "r":
			return m, refreshStoresCmd()

		case "enter", "l":
			return m, selectItemCmd(m.cursor)
		}
	}

	return m, nil
}

