Rust
use tokio::net::UnixListener;
use tokio::io::{AsyncReadExt, AsyncWriteExt};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let _ = std::fs::remove_file("/tmp/store.sock");
    let listener = UnixListener::bind("/tmp/store.sock")?;

    loop {
        let (mut stream, _) = listener.accept().await?;

        tokio::spawn(async move {
            let mut buf = vec![0u8; 4096];
            let n = stream.read(&mut buf).await.unwrap();
            let req: Request = serde_json::from_slice(&buf[..n]).unwrap();

            let result = match req.method.as_str() {
                "store.search" => serde_json::json!(["firefox", "chromium"]),
                "store.list" => serde_json::json!(["flathub", "nixpkgs"]),
                _ => serde_json::json!(null),
            };

            let resp = Response {
                jsonrpc: "2.0",
                result,
                id: req.id,
            };

            let data = serde_json::to_vec(&resp).unwrap();
            stream.write_all(&data).await.unwrap();
        });
    }
}

