use serde_json::{json, Value};
use std::{
    io::{BufReader, BufRead, Write},
    os::unix::net::{UnixListener, UnixStream},
    thread,
};

fn handle_request(req: Value, stream: &mut UnixStream) {
    let resp = match req["method"].as_str() {
        Some("search") => {
            let query = req["params"]["query"].as_str().unwrap_or("");
            json!({
                "jsonrpc": "2.0",
                "id": req["id"],
                "result": [
                    { "name": "firefox", "version": "123.0" },
                    { "name": "firefox-beta", "version": "124.0b1" }
                ],
                "events": [
                    {"type": "progress", "message": format!("Searching {}", query)}
                ]
            })
        }
        _ => json!({
            "jsonrpc": "2.0",
            "id": req["id"],
            "error": { "code": -32601, "message": "Method not found" }
        })
    };

    writeln!(stream, "{}", resp.to_string()).unwrap();
}

fn handle_client(mut stream: UnixStream) {
    let reader = BufReader::new(stream.try_clone().unwrap());
    for line in reader.lines() {
        if let Ok(line) = line {
            if let Ok(req) = serde_json::from_str::<Value>(&line) {
                handle_request(req, &mut stream);
            }
        }
    }
}

pub fn run_socket_server(path: &str) {
    let _ = std::fs::remove_file(path);
    let listener = UnixListener::bind(path).unwrap();
    println!("IPC socket listening on {}", path);

    for stream in listener.incoming() {
        if let Ok(stream) = stream {
            thread::spawn(move || handle_client(stream));
        }
    }
}

