#[derive(Serialize, Deserialize, Clone)]
pub struct Node {
    pub id: String,
    pub node_type: String, // "package" or "store"
}

#[derive(Serialize, Deserialize, Clone)]
pub struct Edge {
    pub from: String,
    pub to: String,
