}

#[derive(Default)]
pub struct Graph {
    pub nodes: HashMap<String, Node>,
    pub edges: Vec<Edge>,
}

impl Graph {
    pub fn add_node(&mut self, id: &str, node_type: &str) {
        self.nodes.entry(id.to_string())
            .or_insert(Node { id: id.to_string(), node_type: node_type.to_string() });
    }

    pub fn add_edge(&mut self, from: &str, to: &str, edge_type: &str) {
        self.edges.push(Edge { from: from.to_string(), to: to.to_string(), edge_type: edge_type.to_string() });
    }

    pub fn to_json(&self) -> String {
        serde_json::to_string(&self).unwrap()
    }
}

