use std::{thread, time::Duration};

fn main() {
    // Start IPC server in a thread
    std::thread::spawn(|| soar_ui_core::ipc::run_socket_server("/tmp/soar.sock"));

    // Periodic federation sync
    let mut federation = soar_ui_core::federation::Federation::new();
    loop {
        for store in federation.stores.values() {
            let _ = federation.sync_store(store);
        }

        let conflicts = federation.detect_conflicts();
        for conflict in conflicts {
            // Send via IPC to all connected frontends
            soar_ui_core::ipc::broadcast_event("solver_conflict", conflict);
        }

        // Sleep for configurable interval
        thread::sleep(Duration::from_secs(60 * 5));
    }
}

