C++
grpc::Status CMeasurementApiServicer::registerClient(
    grpc::ServerContext* context,
    const pbdef::srvRequest* request,
    grpc::ServerWriter<pbdef::srvRequest>* writer) {

    ClientManager cm;
    OutCommunicator pm;

    cm.addNewClient(request->uid());
    {
        libpqxx::work txn(pgConn);
        txn.exec("INSERT INTO clients (client_uid) VALUES ($1) ON CONFLICT (client_uid) DO UPDATE SET last_seen = NOW();", request->uid());
        txn.commit();
    }
    pm.addMessage("UID '" + request->uid() + "' registered");

    while (true) {
        auto req = cm.getNextRequestOfClient(request->uid());
        if (!req) break;
        if (!writer->Write(*req)) break;  // Stream the request
    }

    return grpc::Status::OK;
}

