#include "ExternalClient.hpp"

class ClientManager {
public:
    // Constructor
    ClientManager();

    // Client management methods
    bool registerClient(const std::string& uid, const std::string& clientName);
    std::shared_ptr<ExternalClient> getClient(const std::string& uid);
    bool removeClient(const std::string& uid);
    bool clientExists(const std::string& uid) const;

private:
    std::unordered_map<std::string, std::shared_ptr<ExternalClient>> clients;
