C++
#include "ClientManager.hpp"

// Constructor
ClientManager::ClientManager() {}

// Register a new client
bool ClientManager::registerClient(const std::string& uid, const std::string& clientName) {
    std::lock_guard<std::mutex> lock(clientsMutex);

    if (clients.find(uid) != clients.end()) {
        // Client with the same UID already exists
        return false;
    }

    clients[uid] = std::make_shared<ExternalClient>(uid, clientName);
    return true;
}

// Retrieve an existing client
std::shared_ptr<ExternalClient> ClientManager::getClient(const std::string& uid) {
    std::lock_guard<std::mutex> lock(clientsMutex);

    auto it = clients.find(uid);
    if (it != clients.end()) {
        return it->second;
    }

    // Client with the specified UID does not exist
    return nullptr;
}

// Remove a client
bool ClientManager::removeClient(const std::string& uid) {
    std::lock_guard<std::mutex> lock(clientsMutex);

    auto it = clients.find(uid);
    if (it != clients.end()) {
        clients.erase(it);
        return true;
    }

    // Client with the specified UID does not exist
    return false;
}

// Check if a client exists
bool ClientManager::clientExists(const std::string& uid) const {
    std::lock_guard<std::mutex> lock(clientsMutex);
    return clients.find(uid) != clients.end();
}

