class CMeasurementApiServicer final : public api::MeasurementApi::Service {
private:
    std::shared_ptr<PgConnectorFactory> pgFactory;
    std::shared_ptr<pqxx::connection> pgConn;
    std::unordered_set<std::string> allowedMgmtClients;

public:
    CMeasurementApiServicer(std::shared_ptr<PgConnectorFactory> pgfac, const std::unordered_set<std::string>& allowedClients)
        : pgFactory(std::move(pgfac)), allowedMgmtClients(allowedClients) {
        pgConn = std::make_shared<pqxx::connection>(pgFactory->createConnection());
    }

    void logClientWasSeenNow(const std::string& clientUid) {
        pqxx::work txn(*pgConn);
        txn.exec_params("UPDATE clients SET last_seen = NOW() WHERE client_uid = $1", clientUid);
        txn.commit();
    }

    grpc::Status RegisterClient(grpc::ServerContext* context, const api::ClientRequest* request, grpc::ServerWriter<api::SrvRequest>* writer) override {
        ClientManager cm;
        OutCommunicator pm;
        cm.addNewClient(request->uid());

        pqxx::work txn(*pgConn);
        txn.exec_params("INSERT INTO clients (client_uid) VALUES ($1) ON CONFLICT (client_uid) DO UPDATE SET last_seen = NOW()", request->uid());
        txn.commit();

        pm.addMessage("UID '" + request->uid() + "' registered");

        while (true) {
            std::optional<api::SrvRequest> req = cm.getNextRequestOfClient(request->uid());
            if (!req) {
                break;
            }
            writer->Write(*req);
        }
        return grpc::Status::OK;
    }

    grpc::Status PutClientResponse(grpc::ServerContext* context, const api::ClientResponse* resp, api::Nothing* nothing) override {
        ClientManager cm;
        if (resp->msg_type() == api::ClientResponseType::INTRODUCE_CLIENT) {
            std::string peer = context->peer();
            // Additional processing for client introduction (e.g., extracting IP)
            cm.addNewResponseToRequest(resp->client_uid(), *resp);
        }
        logClientWasSeenNow(resp->client_uid());
        return grpc::Status::OK;
    }

    grpc::Status PutMeasurementList(grpc::ServerContext* context, grpc::ServerReader<api::RemoteMeasurementName>* reader, api::Nothing* nothing) override {
        OutCommunicator pm;
        api::RemoteMeasurementName remoteMsmtName;
        while (reader->Read(&remoteMsmtName)) {
            logClientWasSeenNow(remoteMsmtName.client_uid());
            pm.addMessage(remoteMsmtName.name());
        }
        return grpc::Status::OK;
    }

    grpc::Status PutMeasurement(grpc::ServerContext* context, grpc::ServerReader<api::MeasurementData>* reader, grpc::ServerWriter<api::SampleAck>* writer) override {
        pqxx::work txn(*pgFactory->createConnection());
        std::string lastMsmtId;

        api::MeasurementData msmtData;
        while (reader->Read(&msmtData)) {
            std::string msmtId = msmtData.msmt_id();

            if (msmtId != lastMsmtId) {
                txn.exec_params("INSERT INTO clients (client_uid) VALUES ($1) ON CONFLICT DO NOTHING", msmtData.client_uid());
                txn.exec_params("INSERT INTO measurements (shared_measurement_id, client_uid) VALUES ($1, $2) ON CONFLICT DO NOTHING",
                                msmtId, msmtData.client_uid());
                txn.commit();
                lastMsmtId = msmtId;
            }

            api::SampleAck ack;
            ack.set_sample_id(msmtData.sample_id());
            writer->Write(ack);
        }
        return grpc::Status::OK;
    }

    grpc::Status GetMsmtSttngsAndStart(grpc::ServerContext* context, const api::ClientRequest* request, api::MsmtSettings* settings) override {
        ClientManager cm;
        if (cm.isClientLoggedIn(request->uid())) {
            auto msmtSettings = cm.getMsmtSettingsOfClient(request->uid());
            settings->set_pp_device(msmtSettings.ppDevice);
            settings->set_pp_sampling_interval(msmtSettings.ppSamplingInterval);
            settings->set_upload_interval_min(msmtSettings.uploadIntervalMin);
            settings->set_client_uid(request->uid());
            logClientWasSeenNow(request->uid());
        }
        return grpc::Status::OK;
    }

    grpc::Status SetMsmtSettings(grpc::ServerContext* context, const api::MsmtSettings* request, api::Nothing* nothing) override {
        if (!isValidMgmtClient(request->client_uid())) {
            return grpc::Status(grpc::StatusCode::UNAUTHENTICATED, "This method needs authentication. Please set credentials.");
        }
        ClientManager cm;
        cm.setMsmtSettingsOfClient(request->client_uid(), request->pp_device(), request->pp_sampling_interval(), request->upload_interval_min());
        return grpc::Status::OK;
    }

private:
    bool isValidMgmtClient(const std::string& clientId) {
        return allowedMgmtClients.find(clientId) != allowedMgmtClients.end();
    }
};

