import React, { useEffect, useRef } from "react";
import { Terminal } from "xterm";
import { FitAddon } from "xterm-addon-fit";
import "xterm/css/xterm.css";

const TerminalComponent = ({ containerId }) => {
    const terminalRef = useRef(null);
    const socketRef = useRef(null);
    const term = useRef(new Terminal({ cursorBlink: true }));
    const fitAddon = useRef(new FitAddon());

    useEffect(() => {
        if (!terminalRef.current) return;

        // Attach xterm.js to the DOM
        term.current.loadAddon(fitAddon.current);
        term.current.open(terminalRef.current);
        fitAddon.current.fit();

        // Connect to the WebSocket
        socketRef.current = new WebSocket(`ws://localhost:8000/ws/terminal/${containerId}/`);

        socketRef.current.onopen = () => {
            term.current.writeln("Connected to container...");
        };

        socketRef.current.onmessage = (event) => {
            term.current.write(event.data);
        };

        socketRef.current.onerror = (err) => {
            term.current.writeln(`Error: ${err.message}`);
        };

        socketRef.current.onclose = () => {
            term.current.writeln("Disconnected from container.");
        };

        // Send user input from terminal to WebSocket
        term.current.onData((data) => {
            socketRef.current.send(data);
        });

        return () => {
            term.current.dispose();
            socketRef.current?.close();
        };
    }, [containerId]);

    return <div ref={terminalRef} style={{ width: "100%", height: "100%" }} />;
};

export default TerminalComponent;

