import React, { useEffect, useRef, useState } from "react";

const Terminal = () => {
  const [socket, setSocket] = useState<WebSocket | null>(null);
  const [connected, setConnected] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const outputRef = useRef<HTMLDivElement>(null);

  const [messages, setMessages] = useState<string[]>([]);

  useEffect(() => {
    const ws = new WebSocket("ws://localhost:8000/ws/terminal/?cmd=/bin/sh");
    setSocket(ws);

    ws.onopen = () => {
      console.log("WebSocket connected ✅");
      setConnected(true);
    };

    ws.onmessage = (event) => {
      const data = event.data as string;
      setMessages((prev) => [...prev, data]);
      // Scroll down automatically
      if (outputRef.current) {
        outputRef.current.scrollTop = outputRef.current.scrollHeight;
      }
    };

    ws.onclose = () => {
      console.log("WebSocket closed ❌");
      setConnected(false);
    };

    ws.onerror = (error) => {
      console.error("WebSocket error:", error);
    };

    return () => {
      ws.close();
    };
  }, []);

  const handleSend = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!socket || !connected || !inputRef.current) return;

    const input = inputRef.current.value;
    if (input.trim() !== "") {
      socket.send(input + "\n"); // Important: send newline
      inputRef.current.value = "";
    }
  };

  return (
    <div className="p-4 bg-black text-green-400 font-mono h-screen flex flex-col">
      <div
        ref={outputRef}
        className="flex-1 overflow-y-auto mb-2 whitespace-pre-wrap"
      >
        {messages.map((msg, idx) => (
          <div key={idx}>{msg}</div>
        ))}
      </div>
      <form onSubmit={handleSend} className="flex">
        <input
          ref={inputRef}
          type="text"
          className="flex-1 p-2 bg-gray-800 text-green-400 border-none outline-none"
          placeholder={connected ? "Type a command..." : "Connecting..."}
          disabled={!connected}
        />
        <button
          type="submit"
          className="p-2 bg-green-600 text-black font-bold"
          disabled={!connected}
        >
          Send
        </button>
      </form>
    </div>
  );
};

export default Terminal;

