// src/Terminal.js
import React, { useEffect, useRef } from "react";
import { Terminal } from "xterm";
import { FitAddon } from "xterm-addon-fit";
import "xterm/css/xterm.css";

const Terminal = ({ containerId, shellCommand = "/bin/sh" }) => {
  const terminalRef = useRef(null);
  const term = useRef(null);
  const fitAddon = useRef(null);
  const socketRef = useRef(null);

  useEffect(() => {
    // 1. Initialize terminal + fit addon
    term.current = new Terminal({
      cursorBlink: true,
      cols: 80,
      rows: 24,
    });
    fitAddon.current = new FitAddon();
    term.current.loadAddon(fitAddon.current);

    // 2. Attach terminal to DOM
    term.current.open(terminalRef.current);
    fitAddon.current.fit();

    // 3. Build WebSocket URL with query params
    const params = new URLSearchParams();
    params.set("cmd", encodeURIComponent(shellCommand));
    const url = `ws://localhost:8000/ws/terminal/${containerId}/?${params.toString()}`;

    // 4. Connect
    socketRef.current = new WebSocket(url);

    socketRef.current.onopen = () => {
      term.current.writeln(`\x1b[32mConnected to container ${containerId}\x1b[0m`);
    };

    socketRef.current.onmessage = (evt) => {
      term.current.write(evt.data);
      fitAddon.current.fit();
    };

    socketRef.current.onerror = (err) => {
      term.current.writeln(`\x1b[31mWebSocket error\x1b[0m`);
      console.error("WS error:", err);
    };

    socketRef.current.onclose = () => {
      term.current.writeln(`\x1b[33mDisconnected\x1b[0m`);
    };

    // 5. When user types, send to container
    term.current.onData((data) => {
      if (socketRef.current.readyState === WebSocket.OPEN) {
        socketRef.current.send(data);
      }
    });

    // 6. Handle window resize
    const handleResize = () => fitAddon.current.fit();
    window.addEventListener("resize", handleResize);

    // Cleanup on unmount
    return () => {
      window.removeEventListener("resize", handleResize);
      socketRef.current.close();
      term.current.dispose();
    };
  }, [containerId, shellCommand]);

  return (
    <div
      ref={terminalRef}
      style={{
        width: "100%",
        height: "100%",
        backgroundColor: "#000",
      }}
    />
  );
};

export default Terminal;

