// src/components/ShellSelector.tsx
import React, { useEffect, useState } from "react";

interface ShellSelectorProps {
  containerId: string;
  value: string;
  onChange: (shell: string) => void;
}

export const ShellSelector: React.FC<ShellSelectorProps> = ({
  containerId,
  value,
  onChange,
}) => {
  const [shells, setShells] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchShells = async () => {
      setLoading(true);
      setError(null);
      try {
        const res = await fetch(
          `/api/containers/${encodeURIComponent(containerId)}/shells`
        );
        if (!res.ok) throw new Error(`Status ${res.status}`);
        const data: string[] = await res.json();
        setShells(data);
      } catch (err: any) {
        console.error(err);
        setError("Could not load shells");
      } finally {
        setLoading(false);
      }
    };
    fetchShells();
  }, [containerId]);

  if (loading) return <div>Loading shells…</div>;
  if (error) return <div className="text-red-500">{error}</div>;

  return (
    <label className="flex items-center">
      Shell:
      <select
        className="ml-2 p-1 border rounded"
        value={value}
        onChange={(e) => onChange(e.target.value)}
      >
        {shells.map((sh) => (
          <option key={sh} value={sh}>
            {sh}
          </option>
        ))}
      </select>
    </label>
  );
};

